const feathers = require('@feathersjs/feathers');
const express = require('@feathersjs/express');
const { Forbidden, NotFound } = require('@feathersjs/errors');
const knex = require('knex')({ client: 'pg', connection: process.env.DB_URL });

const app = express(feathers());
app.use(express.json());
app.configure(express.rest());

class MerchantOrdersService {
  async get(id, params) {
    const merchantId = params.user.merchantId;
    const order = await knex('merchant_orders')
      .where({ id, merchant_id: merchantId })
      .first();

    if (!order) {
      throw new NotFound('Order not found or does not belong to merchant');
    }
    return order;
  }

  async remove(id, params) {
    const merchantId = params.user.merchantId;
    const deleted = await knex('merchant_orders')
      .where({ id, merchant_id: merchantId })
      .del();

    if (!deleted) {
      throw new NotFound('Order not found or does not belong to merchant');
    }
    return { id, deleted: true };
  }
}

app.use('/merchant-orders', new MerchantOrdersService());

app.service('merchant-orders').hooks({
  before: {
    all: [
      async (context) => {
        if (!context.params.user || context.params.user.status !== 'ACTIVE') {
          throw new Forbidden('Merchant account must be active');
        }
      }
    ]
  }
});
